import { useEffect, useState } from 'react'

import { useQuery } from 'cozy-client'
import { useDataProxy } from 'cozy-dataproxy-lib'

import logger from '@/lib/logger'
import { buildRecentQuery } from '@/queries'

const useDataProxyRecents = () => {
  const [data, setData] = useState(null)
  const [fetchStatus, setFetchStatus] = useState('loading')
  const [error, setError] = useState(null)
  const [useFallback, setUseFallback] = useState(false)
  const dataProxy = useDataProxy()

  // Fallback query using buildRecentQuery
  const recentQuery = buildRecentQuery()
  const fallbackQueryResult = useQuery(
    recentQuery.definition,
    recentQuery.options
  )

  useEffect(() => {
    const fetchRecents = async () => {
      setFetchStatus('loading')
      setError(null)
      try {
        const data = await dataProxy.recents()
        setData(data)
        setFetchStatus('loaded')
        setUseFallback(false)
      } catch (err) {
        logger.error('Error fetching recents', err)
        setError(err)
        setUseFallback(true)
      }
    }

    if (dataProxy.dataProxyServicesAvailable) {
      fetchRecents()
    } else {
      setUseFallback(true)
    }
  }, [dataProxy])

  // Use fallback query result if dataProxy failed or is not available
  useEffect(() => {
    if (useFallback && fallbackQueryResult.data) {
      setData(fallbackQueryResult.data)
      setFetchStatus('loaded')
      setError(null)
    } else if (useFallback && fallbackQueryResult.fetchStatus === 'error') {
      setFetchStatus('error')
      setError(fallbackQueryResult.error)
    } else if (useFallback && fallbackQueryResult.fetchStatus === 'loading') {
      setFetchStatus('loading')
    }
  }, [useFallback, fallbackQueryResult])

  return { data, fetchStatus, error }
}

export default useDataProxyRecents
